window.BOOK={"key":"qawaid","app":"mutoon-qawaid","lsk":"mutoon_qawaid_v1","prefix":"qa_","title":"منظومة القواعد الفقهية","sub":"القواعد الفقهية · عبد الرحمن بن ناصر السعدي (ت ١٣٧٦هـ) · ٤٩ بيتًا","poems":[{"id":"qawaid","title":"منظومة القواعد الفقهية","nazim":"عبد الرحمن بن ناصر بن عبد الله آل سعدي","death":"ت ١٣٧٦هـ","meter":"الرجز","source":"جامع الكتب الإسلامية: منظومة القواعد الفقهية، كراسة طالب العلم (موقع الشيخ السعدي، دار الميمان ١٤٣١هـ)","srcUrl":"https://ketabonline.com/ar/books/24751","note":"اللفظ من نشرة موقع الشيخ السعدي المقابلة على النسخة الخطية (٤٩ بيتًا)، والشكل من أبيات «شرح منظومة القواعد الفقهية» للسعدي نفسه، وهو مشكول تام (جامع الكتب الإسلامية ١٠٢٩٧٧)، وقوبل كلمةً كلمةً بسكربت عليه وعلى نشرة المنظومة مع تعليقات الشيخ (٢٩٤٦٧). في الشرحين سقط بيتان، فأُخذا من النشرة الخطية، وأُكمل شكلهما. وصُحّحت أخطاء شكل يسيرة بالوزن والإعراب، وكلها في تقرير المصادر.","verses":[["الْحَمْدُ لِلَّهِ الْعَلِيِّ الْأَرْفَقِ","وَجَامِعِ الْأَشْيَاءِ وَالْمُفَرِّقِ"],["ذِي النِّعَمِ الْوَاسِعَةِ الْغَزِيرَهْ","وَالْحِكَمِ الْبَاهِرَةِ الْكَثِيرَهْ"],["ثُمَّ الصَّلَاةُ مَعْ سَلَامٍ دَائِمِ","عَلَى الرَّسُولِ الْقُرَشِيِّ الْخَاتمِ"],["وَآلِهِ وَصَحْبِهِ الْأَبْرَارِ","الْحَائِزِي مَرَاتِبَ الْفَخَارِ"],["اعْلَمْ هُدِيتَ أَنَّ أَفْضَلَ الْمِنَنْ","عِلْمٌ يُزِيلُ الشَّكَّ عَنْكَ وَالدَّرَنْ"],["وَيَكْشِفُ الْحَقَّ لِذِي الْقُلُوبِ","وَيُوصِلُ الْعَبْدَ إِلَى الْمَطْلُوبِ"],["فَاحْرِصْ عَلَى فَهْمِكَ لِلْقَوَاعِدِ","جَامِعَةِ الْمَسَائِلِ الشَّوَارِدِ"],["فَتَرْتَقِي فِي الْعِلْمِ خَيْرَ مُرْتَقَى","وَتَقْتَفِي سُبْلَ الَّذِي قَدْ وُفِّقَا"],["وَهَذِهِ قَوَاعِدٌ نَظَمْتُهَا","مِنْ كُتْبِ أَهْلِ الْعِلْمِ قَدْ حَصَّلْتُهَا"],["جَزَاهُمُ الْمَوْلَى عَظِيمَ الْأَجْرِ","وَالْعَفْوَ مَعْ غُفْرَانِهِ وَالْبِرِّ"],["وَالنِّيَّةُ شَرْطٌ لِسَائِرِ الْعَمَلْ","بِهَا الصَّلَاحُ وَالْفَسَادُ لِلْعَمَلْ"],["الدِّينُ مَبْنِيٌّ عَلَى الْمَصَالِحِ","فِي جَلْبِهَا وَالدَّرْءِ لِلْقَبَائِحِ"],["فَإِنْ تَزَاحَمْ عَدَدُ الْمَصَالِحِ","يُقَدَّمُ الْأَعْلَى مِنَ الْمَصَالِحِ"],["وَضِدُّهُ تَزَاحُمُ الْمَفَاسِدِ","يُرْتَكَبُ الْأَدْنَى مِنَ الْمَفَاسِدِ"],["وَمِنْ قَوَاعِدِ الشَّرِيعَةِ التَّيْسِيرُ","فِي كُلِّ أَمْرٍ نَابَهُ تَعْسِيرُ"],["وَلَيْسَ وَاجِبٌ بِلَا اقْتِدَارِ","وَلَا مُحَرَّمٌ مَعَ اضْطِرَارِ"],["وَكُلُّ مَحْظُورٍ مَعَ الضَّرُورَهْ","بِقَدْرِ مَا تَحْتَاجُهُ الضَّرُورَهْ"],["وَتَرْجِعُ الْأَحْكَامُ لِلْيَقِينِ","فَلَا يُزِيلُ الشَّكُّ لِلْيَقِينِ"],["وَالْأَصْلُ فِي مِيَاهِنَا الطَّهَارَهْ","وَالْأَرْضِ وَالثِّيَابِ وَالْحِجَارَهْ"],["وَالْأَصْلُ فِي الْأَبْضَاعِ وَاللُّحُومِ","وَالنَّفْسِ وَالْأَمْوَالِ لِلْمَعْصُومِ"],["تَحْرِيمُهَا حَتَّى يَجِيءَ الْحِلُّ","فَافْهَمْ هَدَاكَ اللَّهُ مَا يُمَلُّ"],["وَالْأَصْلُ فِي عَادَاتِنَا الْإِبَاحَهْ","حَتَّى يَجِيءَ صَارِفُ الْإِبَاحَهْ"],["وَلَيْسَ مَشْرُوعًا مِنَ الْأُمُورْ","غَيْرُ الَّذِي فِي شَرْعِنَا مَذْكُورْ"],["وَسَائِلُ الْأُمُورِ كَالْمَقَاصِدِ","وَاحْكُمْ بِهَذَا الْحُكْمِ لِلزَّوَائِدِ"],["وَالْخَطَأُ وَالْإِكْرَاهُ وَالنِّسْيَانُ","أَسْقَطَهُ مَعْبُودُنَا الرَّحْمَانُ"],["لَكِنْ مَعَ الْإِتْلَافِ يَثْبُتُ الْبَدَلْ","وَيَنْتَفِي التَّأْثِيمُ عَنْهُ وَالزَّلَلْ"],["وَمِنْ مَسَائِلِ الْأَحْكَامِ فِي التَّبَعْ","يَثْبُتُ لَا إِذَا اسْتَقَلَّ فَوَقَعْ"],["وَالْعُرْفُ مَعْمُولٌ بِهِ إِذَا وَرَدْ","حُكْمٌ مِنَ الشَّرْعِ الشَّرِيفِ لَمْ يُحَدْ"],["مُعَاجِلُ الْمَحْظُورِ قَبْلَ آنِهِ","قَدْ بَاءَ بِالْخُسْرَانِ مَعْ حِرْمَانِهِ"],["وَإِنْ أَتَى التَّحْرِيمُ فِي نَفْسِ الْعَمَلْ","أَوْ شَرْطِهِ فَذُو فَسَادٍ وَخَلَلْ"],["وَمُتْلِفُ مُؤْذِيهِ لَيْسَ يَضْمَنُ","بَعْدَ الدِّفَاعِ بِالَّتِي هِيَ أَحْسَنُ"],["وَأَلْ تُفِيدُ الْكُلَّ فِي الْعُمُومِ","فِي الْجَمْعِ وَالْإِفْرَادِ كَالْعَلِيمِ"],["وَالنَّكِرَاتُ فِي سِيَاقِ النَّفْيِ","تُعْطِي الْعُمُومَ أَوْ سِيَاقِ النَّهْيِ"],["كَذَاكَ مَنْ وَمَا تُفِيدَانِ مَعَا","كُلَّ الْعُمُومِ يَا أُخَيَّ فَاسْمَعَا"],["وَمِثْلُهُ الْمُفْرَدُ إِذْ يُضَافُ","فَافْهَمْ هُدِيتَ الرُّشْدَ مَا يُضَافُ"],["وَلَا يَتِمُّ الْحُكْمُ حَتَّى تَجْتَمِعْ","كُلُّ الشُّرُوطِ وَالْمَوَانِعْ تَرْتَفِعْ"],["وَمَنْ أَتَى بِمَا عَلَيْهِ مِنْ عَمَلْ","قَدِ اسْتَحَقَّ مَا لَهُ عَلَى الْعَمَلْ"],["وَيُفْعَلُ الْبَعْضُ مِنَ الْمَأْمُورِ","إِنْ شَقَّ فِعْلُ سَائِرِ الْمَأْمُورِ"],["وَكُلُّ مَا نَشَا عَنِ الْمَأْذُونِ","فَذَاكَ أَمْرٌ لَيْسَ بِالْمَضْمُونِ"],["وَكُلُّ حُكْمٍ دَائِرٌ مَعْ عِلَّتِهْ","وَهْيَ الَّتِي قَدْ أَوْجَبَتْ لِشِرْعَتِهْ"],["وَكُلُّ شَرْطٍ لَازِمٌ لِلْعَاقِدِ","فِي الْبَيْعِ وَالنِّكَاحِ وَالْمَقَاصِدِ"],["إِلَّا شُرُوطًا حَلَّلَتْ مُحَرَّمَا","أَوْ عَكْسُهُ فَبَاطِلَاتٌ فَاعْلَمَا"],["تُسْتَعْمَلُ الْقُرْعَةُ عِنْدَ الْمُبْهَمِ","مِنَ الْحُقُوقِ أَوْ لَدَى التَّزَاحُمِ"],["وَإِنْ تَسَاوَى الْعَمَلَانِ اجْتَمَعَا","وَفِعْلُ أَحْدِهِمَا فَاسْتَمِعَا"],["وَكُلُّ مَشْغُولٍ فَلَا يُشَغَّلُ","مِثَالُهُ الْمَرْهُونُ وَالْمُسَبَّلُ"],["وَمَنْ يُؤَدِّ عَنْ أَخِيهِ وَاجِبَا","لَهُ الرُّجُوعُ إِنْ نَوَى يُطَالِبَا"],["وَالْوَازِعُ الطَّبْعِيُّ عَنِ الْعِصْيَانِ","كَالْوَازِعِ الشَّرْعِيِّ بِلَا نُكْرَانِ"],["وَالْحَمْدُ لِلَّهِ عَلَى التَّمَامِ","فِي الْبَدْءِ وَالْخِتَامِ وَالدَّوَامِ"],["ثُمَّ الصَّلَاةُ مَعْ سَلَامٍ شَائِعِ","عَلَى النَّبِيِّ وَصَحْبِهِ وَالتَّابِعِ"]],"secs":{"1":"مُقَدِّمَةٌ","11":"فَصْلٌ"}}],"sharh":false};
